package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Master { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String name; @NotBlank private String specialization; @Min(0) @Max(50) private int experienceYears; public Master(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public int getExperienceYears(){return experienceYears;} public void setExperienceYears(int v){experienceYears=v;} }
